examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
    MonarchBanner(title = {{items.0.title}}, message = {{items.0.body}}, tone = {{items.0.tone|tone}})
    MonarchBanner(title = {{items.1.title}}, message = null, tone = {{items.1.tone|tone}})
    MonarchBanner(
        title = {{items.2.title}},
        message = null,
        tone = {{items.2.tone|tone}},
        action = {
            MonarchButton(
                text = {{items.2.action.label}},
                onClick = {},
                variant = MonarchButtonVariant.{{items.2.action.variant|pascal}},
                size = MonarchButtonSize.{{items.2.action.size|pascal}},
            )
        },
    )
    MonarchBanner(
        title = {{items.3.title}},
        message = {{items.3.body}},
        tone = {{items.3.tone|tone}},
        announcement = MonarchBannerAnnouncement.{{items.3.live|pascal}},
    )
}

